package com.martorell.albert.basketcoach.data.network.dto

import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable

/**
 * OpenAI-compatible chat completion response payload.
 *
 * @property id Unique completion identifier.
 * @property choices List of completion choices generated by the model.
 */
@Serializable
data class ChatCompletionResponseDto(
    @SerialName("id")
    val id: String? = null,
    @SerialName("choices")
    val choices: List<ChoiceDto> = emptyList()
)

/**
 * An individual choice returned in a chat completion response.
 *
 * @property index Choice index.
 * @property message The generated message payload.
 */
@Serializable
data class ChoiceDto(
    @SerialName("index")
    val index: Int? = null,
    @SerialName("message")
    val message: ChatMessageDto
)
